def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Continue each diagonal pair from its lower-row end, stopping at an
    # occupied cell or the edge of the grid.
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r][c] == grid[r + 1][nc] != background:
                    color = grid[r][c]
                    rr, cc = r + 2, nc + dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != background:
                            break
                        out[rr][cc] = color
                        rr += 1
                        cc += dc
    return out
